reference_solution:
def partition(s):
    res, cur = [], []
    def bt(start):
        if start == len(s):
            res.append(cur[:])
            return
        for end in range(start + 1, len(s) + 1):
            sub = s[start:end]
            if sub == sub[::-1]:
                cur.append(sub)
                bt(end)
                cur.pop()
    bt(0)
    return res

brute_force_solution:
def partition(s):
    n = len(s)
    res = []
    for mask in range(1 << (n - 1)):
        parts, start = [], 0
        for i in range(n - 1):
            if (mask >> i) & 1:
                parts.append(s[start:i + 1])
                start = i + 1
        parts.append(s[start:])
        if all(p == p[::-1] for p in parts):
            res.append(parts)
    return res

